<?php
function fi(string $name):string {$icons=['overview'=>'▦','employees'=>'♙','settings'=>'⚙','departments'=>'▤','designations'=>'◇','roles'=>'◎','account'=>'◉'];return $icons[$name]??'↗';}
function fnav(string $key,string $label):void {global $page;echo '<a href="?page='.h($key).'" '.($page===$key||($key==='employees'&&str_starts_with($page,'employee-'))?'class="selected" aria-current="page"':'').'><span aria-hidden="true">'.fi($key).'</span>'.h($label).'</a>';}
function field(string $key,string $label,array $v,string $type='text',bool $required=false,int $max=190):void {echo '<label>'.h($label).($required?' <span aria-label="required">*</span>':'').'<input type="'.h($type).'" name="'.h($key).'" value="'.h($v[$key]??'').'" maxlength="'.$max.'" '.($required?'required':'').'></label>';}
function choose(string $key,string $label,array $v,array $options):void {echo '<label>'.h($label).'<select name="'.h($key).'">';foreach($options as $o)echo '<option '.(($v[$key]??'')===$o?'selected':'').'>'.h($o).'</option>';echo '</select></label>';}
function fbadge(string $text,bool $ok=true):void {echo '<span class="badge '.($ok?'':'muted-badge').'">'.h($text).'</span>';}
$settingsSections=['settings'=>'Company Profile','departments'=>'Departments','designations'=>'Designations','roles'=>'Roles & Permissions','attendance_settings'=>'Attendance Mode','shifts'=>'Shifts','shift_defaults'=>'Default Shifts','time_policies'=>'Time Policies','biometric_integration'=>'Biometric Integration','company_calendar'=>'Company Calendar','roster'=>'Employee Shift Assignments','holidays'=>'Holidays','devices'=>'Devices','mapping'=>'Employee Mapping','sync'=>'Sync History','raw_logs'=>'Raw Punch Logs'];
$inSettings=isset($settingsSections[$page]);$settingsAllowed=[];foreach($settingsSections as $key=>$label)if(can($pdo,$user,$pages[$key][1])&&(!in_array($key,['devices','mapping','sync','raw_logs'],true)||att_biometric_enabled($pdo)))$settingsAllowed[$key]=$label;
$hasLogo=$installed?(bool)$pdo->query("SELECT id FROM hr_media WHERE purpose='company_logo' LIMIT 1")->fetchColumn():false;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($pages[$page][0])?> · PeopleFlow</title><link rel="stylesheet" href="assets/foundation.css?v=<?=filemtime(dirname(__DIR__,2).'/assets/foundation.css')?>"><script src="assets/foundation.js?v=<?=filemtime(dirname(__DIR__,2).'/assets/foundation.js')?>" defer></script><link rel="stylesheet" href="assets/tables.css?v=<?=filemtime(__DIR__.'/../../assets/tables.css')?>"><script src="assets/tables.js?v=<?=filemtime(__DIR__.'/../../assets/tables.js')?>" defer></script></head><body>
