<div class="app"><header class="topbar"><button class="icon-button menu-toggle" aria-label="Toggle navigation" aria-expanded="false" aria-controls="navigation">☰</button><span class="breadcrumb"><?=h($company['name'])?> <span>›</span> <strong><?=h($pages[$page][0])?></strong></span><div class="top-actions"><button class="icon-button" id="theme-toggle" aria-label="Toggle dark mode">◐</button><a class="user-link" href="?page=account"><span class="avatar small"><?=h(strtoupper(substr($user['name'],0,1)))?></span><span><?=h($user['name'])?><small><?=$user['role']==='super_admin'?'Super Administrator':'Team workspace'?></small></span></a></div></header>
<main id="main"><div class="page-heading"><div><p class="eyebrow"><?=$inSettings?'ADMINISTRATION':'PEOPLEFLOW WORKSPACE'?></p><h1><?=h($inSettings?'Company Settings':($page==='overview'?'Good '.((int)date('H')<12?'morning':'afternoon').', '.explode(' ',$user['name'])[0]:$pages[$page][0]))?></h1><p class="subtitle"><?=h($inSettings?'Manage company, organization and access configurations.':(['overview'=>"Here’s what’s happening with your people today.",'employees'=>'Your complete employee directory, in one place.','settings'=>'The company details used across your workspace.','departments'=>'Organize your teams and their department heads.','designations'=>'Manage job titles and their department assignments.','roles'=>'Create roles and choose exactly what each role can access.'][$page]??'Manage your people with care.'))?></p></div><?php if($installed&&$page==='employees'&&can($pdo,$user,'employees.create')):?><a class="button primary" href="?page=employee-add">+ Add employee</a><?php endif;?></div>
