if($inSettings):?><div class="settings-shell"><nav class="settings-menu card" aria-label="Company settings sections"><?php foreach(['GENERAL'=>['settings'],'ORGANIZATION'=>['departments','designations'],'ATTENDANCE SETUP'=>['attendance_settings','shifts','shift_defaults','roster','time_policies'],'BIOMETRIC'=>['biometric_integration','devices','mapping','sync','raw_logs'],'CALENDAR'=>['holidays','company_calendar'],'ACCESS CONTROL'=>['roles']] as $group=>$keys):$visible=array_filter($keys,fn($key)=>isset($settingsAllowed[$key]));if(!$visible)continue;?><div class="settings-menu-group"><p class="eyebrow"><?=h($group)?></p><?php foreach($visible as $key):?><a href="?page=<?=h($key)?>" <?=$page===$key?'aria-current="page"':''?>><span aria-hidden="true"><?=fi($key)?></span><?=h($settingsAllowed[$key])?></a><?php endforeach;?></div><?php endforeach;?></nav><div class="settings-content"><div class="settings-section-heading"><h2><?=h($settingsSections[$page])?></h2></div><?php endif;
if(isset($corePages[$page]))require dirname(__DIR__).'/core-hr/view.php';elseif($page==='overview')require __DIR__.'/overview.php';elseif(str_starts_with($page,'employee'))require __DIR__.'/people.php';elseif(in_array($page,['settings','departments','designations','roles'],true))require __DIR__.'/settings.php';else require __DIR__.'/account.php';if($inSettings)echo '</div></div>';endif;?>
